import json
def boxes(g):
    from collections import defaultdict
    cells=defaultdict(list)
    for r,row in enumerate(g):
        for c,v in enumerate(row):
            if v: cells[v].append((r,c))
    B={}
    for v,cs in cells.items():
        rs=[a for a,b in cs]; cc=[b for a,b in cs]
        B[v]=(min(rs),min(cc),max(rs),max(cc))
    return B
def transform(g):
    g=[row[:] for row in g]
    B=boxes(g)
    tmpl=None; pat=None
    for v,(r0,c0,r1,c1) in B.items():
        inner=[row[c0+1:c1] for row in g[r0+1:r1]]
        if any(any(row) for row in inner):
            tmpl=v; pat=[row[:] for row in inner]
    ph=len(pat); pw=len(pat[0])
    for v,(r0,c0,r1,c1) in B.items():
        ih=r1-r0-1; iw=c1-c0-1
        if v==tmpl: continue
        if ih>=ph and iw>=pw:
            for i in range(ph):
                for j in range(pw):
                    if pat[i][j]: g[r0+1+i][c0+1+j]=v
        else:
            for r in range(r0,r1+1):
                for c in range(c0,c1+1):
                    g[r][c]=0
    return g
